"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[825],{8765:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2020/02/26/git-basic-usage","metadata":{"permalink":"/parrotbaobao/blog/2020/02/26/git-basic-usage","editUrl":"https://github.com/parrotbaobao/parrotbaobao.github.io/edit/master/blog/blog/2020-02-26-git-basic-usage.md","source":"@site/blog/2020-02-26-git-basic-usage.md","title":"Git \u57fa\u672c\u4f7f\u7528","description":"Git \u662f\u4e00\u4e2a\u5206\u5e03\u5f0f\u7248\u672c\u63a7\u5236\u7cfb\u7edf\uff0c\u7528\u4e8e\u8ddf\u8e2a\u6587\u4ef6\u7684\u66f4\u6539\uff0c\u5c24\u5176\u662f\u7a0b\u5e8f\u4ee3\u7801\u3002\u5b83\u53ef\u4ee5\u5e2e\u52a9\u591a\u4eba\u534f\u4f5c\u5f00\u53d1\uff0c\u5e76\u4fdd\u6301\u4ee3\u7801\u5386\u53f2\u7684\u8bb0\u5f55\u3002\u672c\u6587\u5c06\u4ecb\u7ecd Git \u7684\u4e00\u4e9b\u57fa\u672c\u547d\u4ee4\u548c\u5e38\u89c1\u64cd\u4f5c\u3002","date":"2020-02-26T00:00:00.000Z","tags":[{"inline":true,"label":"Git","permalink":"/parrotbaobao/blog/tags/git"},{"inline":true,"label":"\u4f7f\u7528\u6559\u7a0b","permalink":"/parrotbaobao/blog/tags/\u4f7f\u7528\u6559\u7a0b"},{"inline":true,"label":"\u7248\u672c\u63a7\u5236","permalink":"/parrotbaobao/blog/tags/\u7248\u672c\u63a7\u5236"}],"readingTime":4.3,"hasTruncateMarker":false,"authors":[{"name":"parrot","title":"nothing","url":"https://\u4f60\u7684\u4e2a\u4eba\u7f51\u7ad9.com","imageURL":"https://\u4f60\u7684\u5934\u50cf\u94fe\u63a5.com","key":null,"page":null}],"frontMatter":{"title":"Git \u57fa\u672c\u4f7f\u7528","author":"parrot","author_title":"nothing","author_url":"https://\u4f60\u7684\u4e2a\u4eba\u7f51\u7ad9.com","author_image_url":"https://\u4f60\u7684\u5934\u50cf\u94fe\u63a5.com","tags":["Git","\u4f7f\u7528\u6559\u7a0b","\u7248\u672c\u63a7\u5236"],"date":"2020-02-26T00:00:00.000Z"},"unlisted":false},"content":"Git \u662f\u4e00\u4e2a\u5206\u5e03\u5f0f\u7248\u672c\u63a7\u5236\u7cfb\u7edf\uff0c\u7528\u4e8e\u8ddf\u8e2a\u6587\u4ef6\u7684\u66f4\u6539\uff0c\u5c24\u5176\u662f\u7a0b\u5e8f\u4ee3\u7801\u3002\u5b83\u53ef\u4ee5\u5e2e\u52a9\u591a\u4eba\u534f\u4f5c\u5f00\u53d1\uff0c\u5e76\u4fdd\u6301\u4ee3\u7801\u5386\u53f2\u7684\u8bb0\u5f55\u3002\u672c\u6587\u5c06\u4ecb\u7ecd Git \u7684\u4e00\u4e9b\u57fa\u672c\u547d\u4ee4\u548c\u5e38\u89c1\u64cd\u4f5c\u3002\\n\\n## 1. \u5b89\u88c5 Git\\n\\n\u9996\u5148\uff0c\u4f60\u9700\u8981\u5728\u4f60\u7684\u8ba1\u7b97\u673a\u4e0a\u5b89\u88c5 Git\u3002\u4f60\u53ef\u4ee5\u8bbf\u95ee [Git \u5b98\u7f51](https://git-scm.com/) \u4e0b\u8f7d\u5e76\u5b89\u88c5\u3002\\n\\n```bash\\n# \u5728\u7ec8\u7aef\u4e2d\u8f93\u5165\u4ee5\u4e0b\u547d\u4ee4\uff0c\u68c0\u67e5 Git \u662f\u5426\u5b89\u88c5\u6210\u529f\\ngit --version\\n```\\n\\n\u5982\u679c Git \u5b89\u88c5\u6210\u529f\uff0c\u4f60\u5c06\u770b\u5230 Git \u7684\u7248\u672c\u4fe1\u606f\u3002\\n\\n## 2. Git \u57fa\u672c\u6982\u5ff5\\n\\n*   **\u4ed3\u5e93\uff08Repository\uff09\uff1a** \u5b58\u50a8\u9879\u76ee\u6240\u6709\u6587\u4ef6\u548c\u5386\u53f2\u8bb0\u5f55\u7684\u5730\u65b9\u3002\\n*   **\u5de5\u4f5c\u533a\uff08Working Directory\uff09\uff1a** \u4f60\u5728\u672c\u5730\u8ba1\u7b97\u673a\u4e0a\u7f16\u8f91\u6587\u4ef6\u7684\u76ee\u5f55\u3002\\n*   **\u6682\u5b58\u533a\uff08Staging Area\uff09\uff1a** \u7528\u4e8e\u5b58\u653e\u4f60\u60f3\u8981\u63d0\u4ea4\u7684\u66f4\u6539\u3002\\n*   **\u63d0\u4ea4\uff08Commit\uff09\uff1a** \u5c06\u6682\u5b58\u533a\u7684\u66f4\u6539\u4fdd\u5b58\u5230\u4ed3\u5e93\u7684\u5386\u53f2\u8bb0\u5f55\u4e2d\u3002\\n*   **\u5206\u652f\uff08Branch\uff09\uff1a** \u7528\u4e8e\u5e76\u884c\u5f00\u53d1\u7684\u4e0d\u540c\u4ee3\u7801\u7248\u672c\u3002\\n*   **\u5408\u5e76\uff08Merge\uff09\uff1a** \u5c06\u4e0d\u540c\u5206\u652f\u7684\u66f4\u6539\u5408\u5e76\u5230\u4e00\u8d77\u3002\\n\\n## 3. Git \u5e38\u7528\u547d\u4ee4\\n\\n### 3.1 \u521d\u59cb\u5316\u4ed3\u5e93\\n\\n```bash\\n# \u5728\u9879\u76ee\u6839\u76ee\u5f55\u4e0b\u521d\u59cb\u5316 Git \u4ed3\u5e93\\ngit init\\n```\\n\\n### 3.2 \u6dfb\u52a0\u6587\u4ef6\u5230\u6682\u5b58\u533a\\n\\n```bash\\n# \u6dfb\u52a0\u5355\u4e2a\u6587\u4ef6\u5230\u6682\u5b58\u533a\\ngit add <\u6587\u4ef6\u540d>\\n\\n# \u6dfb\u52a0\u6240\u6709\u66f4\u6539\u7684\u6587\u4ef6\u5230\u6682\u5b58\u533a\\ngit add .\\n```\\n\\n### 3.3 \u63d0\u4ea4\u66f4\u6539\\n\\n```bash\\n# \u63d0\u4ea4\u6682\u5b58\u533a\u7684\u66f4\u6539\uff0c\u5e76\u6dfb\u52a0\u63d0\u4ea4\u4fe1\u606f\\ngit commit -m \\"\u63d0\u4ea4\u4fe1\u606f\\"\\n```\\n\\n### 3.4 \u67e5\u770b\u4ed3\u5e93\u72b6\u6001\\n\\n```bash\\n# \u67e5\u770b\u5f53\u524d\u4ed3\u5e93\u7684\u72b6\u6001\uff0c\u5305\u62ec\u5df2\u4fee\u6539\u4f46\u672a\u6682\u5b58\u7684\u6587\u4ef6\uff0c\u4ee5\u53ca\u5df2\u6682\u5b58\u4f46\u672a\u63d0\u4ea4\u7684\u6587\u4ef6\\ngit status\\n```\\n\\n### 3.5 \u67e5\u770b\u63d0\u4ea4\u5386\u53f2\\n\\n```bash\\n# \u67e5\u770b\u63d0\u4ea4\u5386\u53f2\u8bb0\u5f55\\ngit log\\n```\\n\\n### 3.6 \u521b\u5efa\u548c\u5207\u6362\u5206\u652f\\n\\n```bash\\n# \u521b\u5efa\u4e00\u4e2a\u65b0\u7684\u5206\u652f\\ngit branch <\u5206\u652f\u540d>\\n\\n# \u5207\u6362\u5230\u6307\u5b9a\u5206\u652f\\ngit checkout <\u5206\u652f\u540d>\\n\\n# \u521b\u5efa\u5e76\u5207\u6362\u5230\u65b0\u7684\u5206\u652f\uff08\u5e38\u7528\uff09\\ngit checkout -b <\u5206\u652f\u540d>\\n```\\n\\n### 3.7 \u5408\u5e76\u5206\u652f\\n\\n```bash\\n# \u5207\u6362\u5230\u8981\u5408\u5e76\u5230\u7684\u76ee\u6807\u5206\u652f\\ngit checkout <\u76ee\u6807\u5206\u652f>\\n\\n# \u5c06\u6307\u5b9a\u5206\u652f\u7684\u66f4\u6539\u5408\u5e76\u5230\u5f53\u524d\u5206\u652f\\ngit merge <\u8981\u5408\u5e76\u7684\u5206\u652f>\\n```\\n\\n### 3.8 \u8fdc\u7a0b\u4ed3\u5e93\\n\\n*   **\u514b\u9686\u8fdc\u7a0b\u4ed3\u5e93\uff1a**\\n\\n    ```bash\\n    git clone <\u8fdc\u7a0b\u4ed3\u5e93\u5730\u5740>\\n    ```\\n*   **\u6dfb\u52a0\u8fdc\u7a0b\u4ed3\u5e93\uff1a**\\n\\n    ```bash\\n    git remote add origin <\u8fdc\u7a0b\u4ed3\u5e93\u5730\u5740>\\n    ```\\n*   **\u63a8\u9001\u672c\u5730\u5206\u652f\u5230\u8fdc\u7a0b\u4ed3\u5e93\uff1a**\\n\\n    ```bash\\n    git push origin <\u672c\u5730\u5206\u652f\u540d>:<\u8fdc\u7a0b\u5206\u652f\u540d>\\n\\n    # \u5982\u679c\u672c\u5730\u5206\u652f\u540d\u548c\u8fdc\u7a0b\u5206\u652f\u540d\u76f8\u540c\uff0c\u53ef\u4ee5\u7b80\u5199\u4e3a\uff1a\\n    git push origin <\u5206\u652f\u540d>\\n    ```\\n*   **\u4ece\u8fdc\u7a0b\u4ed3\u5e93\u62c9\u53d6\u66f4\u65b0\uff1a**\\n\\n    ```bash\\n    git pull origin <\u5206\u652f\u540d>\\n    ```\\n\\n## 4. \u5e38\u89c1 Git \u64cd\u4f5c\\n\\n### 4.1 \u64a4\u9500\u66f4\u6539\\n\\n*   **\u64a4\u9500\u5de5\u4f5c\u533a\u7684\u66f4\u6539\uff1a**\\n\\n    ```bash\\n    git checkout -- <\u6587\u4ef6\u540d>\\n    ```\\n*   **\u64a4\u9500\u6682\u5b58\u533a\u7684\u66f4\u6539\uff1a**\\n\\n    ```bash\\n    git reset HEAD <\u6587\u4ef6\u540d>\\n    ```\\n\\n### 4.2 \u89e3\u51b3\u51b2\u7a81\\n\\n\u5f53\u5408\u5e76\u5206\u652f\u65f6\uff0c\u5982\u679c\u4e0d\u540c\u5206\u652f\u5bf9\u540c\u4e00\u6587\u4ef6\u8fdb\u884c\u4e86\u4e0d\u540c\u7684\u4fee\u6539\uff0c\u53ef\u80fd\u4f1a\u53d1\u751f\u51b2\u7a81\u3002\u4f60\u9700\u8981\u624b\u52a8\u89e3\u51b3\u51b2\u7a81\uff0c\u7136\u540e\u91cd\u65b0\u63d0\u4ea4\u3002\\n\\n1.  \u6253\u5f00\u5305\u542b\u51b2\u7a81\u7684\u6587\u4ef6\u3002\\n2.  \u67e5\u627e\u5305\u542b `<<<<<<<`\uff0c`=======` \u548c `>>>>>>>` \u7684\u90e8\u5206\u3002\\n3.  \u624b\u52a8\u7f16\u8f91\u6587\u4ef6\uff0c\u9009\u62e9\u8981\u4fdd\u7559\u7684\u66f4\u6539\uff0c\u5e76\u5220\u9664\u51b2\u7a81\u6807\u8bb0\u3002\\n4.  \u5c06\u89e3\u51b3\u51b2\u7a81\u540e\u7684\u6587\u4ef6\u6dfb\u52a0\u5230\u6682\u5b58\u533a\u3002\\n5.  \u63d0\u4ea4\u66f4\u6539\u3002\\n\\n## 5. \u603b\u7ed3\\n\\n\u672c\u6587\u4ecb\u7ecd\u4e86 Git \u7684\u4e00\u4e9b\u57fa\u672c\u6982\u5ff5\u548c\u5e38\u7528\u547d\u4ee4\u3002\u5e0c\u671b\u8fd9\u4e9b\u4fe1\u606f\u80fd\u5e2e\u52a9\u4f60\u5f00\u59cb\u4f7f\u7528 Git \u8fdb\u884c\u7248\u672c\u63a7\u5236\u3002\\n\\n## 6. \u66f4\u591a\u8d44\u6e90\\n\\n*   [Git \u5b98\u65b9\u7f51\u7ad9](https://git-scm.com/)\\n*   [Pro Git Book](https://git-scm.com/book/zh-cn/v2)\\n\\n```"}]}}')}}]);